import type { ChangedFile, DiffRow, GitHubReviewThread, ReviewThread, ReviewView } from '../../types'
import { ASK_BUTTON_KEY_PREFIX, ASK_ON_LINE_KEY, LINE_NUMBER_BUTTON_KEY_PREFIX } from '../constants'
import { isGitHubThreadOnRow, unplacedGitHubThreadsOf } from '../github-review'
import type { Keymap, ShortcutAction } from '../keymap'
import { anchorKeyOf, fileAnchorPrefixOf, parseAnchorKey, threadsOffTheDiff } from '../questions'
import type { SplitRow, SplitSide } from '../split-rows'
import { languageOfPath } from '../syntax-language'
import { matchCountOf, splitByTerm } from '../watch'
import { fileTypeBadgeOf } from './file-badges'
import { renderFileStats, renderShortcutHint, renderThreadNavigation } from './labels'
import { renderGitHubThread } from './github-threads'
import { ROW_MARKS, rowBackgroundOf, rowColorOf } from './theme'
import { renderThread, renderThreadsAndQuestion, THREAD_INDENT } from './threads'
import type { ExplorerActions, QuestionState, ThreadNavigation, ViewElements } from './types'

// Wider than any pane: its box cuts it to the room left beside the hunk's heading.
const HUNK_RULE = '─'.repeat(400)

export type DiffViewInput = {
  view: ReviewView
  selectedCommitSha: string | null
  selectedFile: ChangedFile | undefined
  diffRows: DiffRow[]
  // The rows paired old against new when the side-by-side view is on, null in the unified view.
  splitRows: SplitRow[] | null
  canSplitView: boolean
  // The row the keyboard's line cursor is on, by its index in diffRows.
  cursorRowIndex: number | null
  hasLineShortcuts: boolean
  // Empty while nothing is watched.
  watchedTerm: string
  canMarkViewed: boolean
  // The keyboard went to a GitHub thread: asking then has Claude address it.
  isOnGitHubThread: boolean
  keymap: Keymap
  isWholeFile: boolean
  diffOffset: number
  diffSkippedLines: number
  visibleDiffRows: number
  threads: ReviewThread[]
  // The GitHub review conversations of the shown file, in the PR view.
  gitHubThreads: GitHubReviewThread[]
  expandedGitHubThreadIds: string[]
  currentThreadId: string | null
  questionState: QuestionState
  threadNavigation: ThreadNavigation
  hotkeyOf: (action: ShortcutAction) => string | undefined
  actions: ExplorerActions
}

export function renderDiffView(ui: ViewElements, input: DiffViewInput) {
  const { Box, Text } = ui
  const { selectedFile } = input
  if (!selectedFile) {
    return (
      <Box paddingX={1}>
        <Text color={ui.theme.muted}>Pick a file on the left.</Text>
      </Box>
    )
  }
  const shownEnd = input.diffOffset + input.visibleDiffRows
  const unplacedGitHubThreads = input.diffOffset === 0 ? unplacedGitHubThreadsOf(input.gitHubThreads, selectedFile.path, input.diffRows) : []
  const threadsOffDiff =
    input.diffOffset === 0
      ? threadsOffTheDiff(
          input.threads,
          fileAnchorPrefixOf(input.view, input.selectedCommitSha, selectedFile.path),
          new Set(input.diffRows.map(row => anchorKeyOf(input.view, input.selectedCommitSha, selectedFile.path, row))),
        )
      : []

  return (
    <Box flexDirection="column">
      {renderFileHeader(ui, selectedFile, input)}
      {input.diffRows.length === 0 && (
        <Box paddingX={1}>
          <Text color={ui.theme.muted}>No textual change in this file.</Text>
        </Box>
      )}
      {unplacedGitHubThreads.map(thread => renderGitHubThread(ui, thread, gitHubThreadInputOf(input)))}
      {threadsOffDiff.map(thread => renderThreadOffDiff(ui, thread, input))}
      <Box flexDirection="column" flexShrink={0} overflow="hidden">
        <Box flexDirection="column" flexShrink={0} marginTop={-input.diffSkippedLines}>
          {input.splitRows
            ? input.splitRows
                .slice(input.diffOffset, shownEnd)
                .map((splitRow, shownRowIndex) => renderSplitRow(ui, splitRow, input.diffOffset + shownRowIndex, selectedFile, input))
            : input.diffRows
                .slice(input.diffOffset, shownEnd)
                .map((row, shownRowIndex) => renderRow(ui, row, input.diffOffset + shownRowIndex, selectedFile, input))}
        </Box>
      </Box>
    </Box>
  )
}

function renderThreadOffDiff(ui: ViewElements, thread: ReviewThread, input: DiffViewInput) {
  const { Box, Text } = ui
  const anchor = parseAnchorKey(thread.anchorKey)
  const lineNumber = anchor?.kind === 'row' ? anchor.lineNumber : null

  return (
    <Box key={`thread-off-diff-${thread.id}`} flexDirection="column" flexShrink={0}>
      <Box marginLeft={THREAD_INDENT} marginTop={1} flexShrink={0}>
        <Text color={ui.theme.muted}>{lineNumber ? `Line ${lineNumber} is` : 'Its line is'} no longer in the diff:</Text>
      </Box>
      {renderThread(ui, thread, input.actions, input.questionState.isAnswerPulseLit)}
    </Box>
  )
}

function renderFileHeader(ui: ViewElements, file: ChangedFile, input: DiffViewInput) {
  const { Box, Button, Text } = ui
  const typeBadge = fileTypeBadgeOf(file.path)
  const rowCount = (input.splitRows ?? input.diffRows).length

  return (
    <Box flexDirection="row" flexShrink={0} backgroundColor={ui.theme.headerBackground} paddingX={1}>
      <Box width={4} flexShrink={0}>
        <Text color={typeBadge.color} bold>
          {typeBadge.badge}
        </Text>
      </Box>
      <Box flexGrow={1} flexShrink={1} minWidth={0}>
        <Text bold color={ui.theme.heading} wrap="truncate-start">
          {file.path}
        </Text>
      </Box>
      {renderThreadNavigation(ui, input.threadNavigation, input.hotkeyOf, input.actions)}
      <Box flexShrink={0} marginRight={3}>
        <Button
          key="toggle-split-view"
          plain
          dimColor={!input.canSplitView}
          hotkey={input.hotkeyOf('toggleSplitView')}
          label={input.splitRows ? '≡ unified' : '⇆ split'}
          onPress={() => (input.canSplitView ? input.actions.toggleSplitView() : input.actions.explainSplitViewWidth())}
        />
      </Box>
      {rowCount > input.visibleDiffRows && (
        <Box flexShrink={0}>
          <Text color={ui.theme.muted}>
            {input.diffOffset + 1}–{Math.min(input.diffOffset + input.visibleDiffRows, rowCount)} / {rowCount}
            {'   '}
          </Text>
        </Box>
      )}
      <Box flexShrink={0}>{renderFileStats(ui, file)}</Box>
    </Box>
  )
}

function renderHunkHeader(ui: ViewElements, row: DiffRow, rowIndex: number, file: ChangedFile, input: DiffViewInput) {
  const { Box, Button, Text } = ui
  const canWidenContext = !file.isUntracked && !input.isWholeFile

  return (
    <Box key={`hunk-${rowIndex}`} flexDirection="row" paddingX={1} flexShrink={0} height={1}>
      <Box flexShrink={1} minWidth={0} overflow="hidden">
        <Text color={ui.theme.hunk} wrap="truncate-end">
          {'@@ '}
          {row.text}{' '}
        </Text>
      </Box>
      {/* No width of its own: the rule only fills what the context leaves, and a long context is cut instead. */}
      <Box flexGrow={1} flexShrink={0} width={0} height={1} overflow="hidden">
        <Text color={ui.theme.border} wrap="truncate-end">
          {HUNK_RULE}
        </Text>
      </Box>
      {canWidenContext && (
        <Box key={`hunk-actions-${rowIndex}`} flexDirection="row" flexShrink={0}>
          <Button
            key={`expand-context-${rowIndex}`}
            plain
            dimColor
            hover={{ color: ui.theme.accent }}
            label=" ↕ more context "
            onPress={() => input.actions.expandContext(file.path)}
          />
          <Button
            key={`whole-file-${rowIndex}`}
            plain
            dimColor
            hover={{ color: ui.theme.accent }}
            label=" whole file "
            onPress={() => input.actions.showWholeFile(file.path)}
          />
        </Box>
      )}
    </Box>
  )
}

function renderRow(ui: ViewElements, row: DiffRow, rowIndex: number, file: ChangedFile, input: DiffViewInput) {
  const { Box, Text } = ui
  if (row.kind === 'hunk') {
    return renderHunkHeader(ui, row, rowIndex, file, input)
  }
  const anchorKey = anchorKeyOf(input.view, input.selectedCommitSha, file.path, row)
  const lineNumbers = `${String(row.oldNumber ?? '').padStart(5)}${String(row.newNumber ?? '').padStart(5)}`
  const isCursor = rowIndex === input.cursorRowIndex

  return (
    <Box key={`row-${rowIndex}`} flexDirection="column" flexShrink={0}>
      <Box flexDirection="row" alignItems="flex-start" backgroundColor={isCursor ? ui.theme.cursorBackground : rowBackgroundOf(ui.theme, row.kind)}>
        {renderAskGutter(ui, rowIndex, anchorKey, isCursor, input)}
        {renderLineNumberButton(ui, rowIndex, anchorKey, lineNumbers, isCursor, input)}
        <Box flexShrink={0} height={1}>
          <Text color={rowColorOf(ui.theme, row.kind)}> {ROW_MARKS[row.kind]} </Text>
        </Box>
        {renderCode(ui, row, file.path, input.watchedTerm)}
      </Box>
      {renderRowThreads(ui, row, rowIndex, file, input)}
    </Box>
  )
}

function renderSplitRow(ui: ViewElements, splitRow: SplitRow, splitIndex: number, file: ChangedFile, input: DiffViewInput) {
  const { Box } = ui
  if (splitRow.kind === 'hunk') {
    return renderHunkHeader(ui, splitRow.row, splitRow.rowIndex, file, input)
  }
  const { left, right } = splitRow
  // An unchanged line stands on both sides but is one line: its buttons and threads go with the right side only.
  const isSameRowOnBothSides = left !== null && left.rowIndex === right?.rowIndex
  const sidesWithThreads = [isSameRowOnBothSides ? null : left, right].flatMap(side => (side ? [side] : []))

  return (
    <Box key={`split-${splitIndex}`} flexDirection="column" flexShrink={0}>
      <Box flexDirection="row" alignItems="stretch">
        {renderSplitSide(ui, left, 'old', !isSameRowOnBothSides, file, input)}
        <Box width={1} flexShrink={0} backgroundColor={ui.theme.border} />
        {renderSplitSide(ui, right, 'new', true, file, input)}
      </Box>
      {sidesWithThreads.map(side => (
        <Box key={`threads-${side.rowIndex}`} flexDirection="column">
          {renderRowThreads(ui, side.row, side.rowIndex, file, input)}
        </Box>
      ))}
    </Box>
  )
}

function renderSplitSide(
  ui: ViewElements,
  side: SplitSide | null,
  version: 'old' | 'new',
  hasButtons: boolean,
  file: ChangedFile,
  input: DiffViewInput,
) {
  const { Box, Text } = ui
  if (side === null) {
    return <Box width="50%" flexGrow={1} minWidth={0} />
  }
  const { row, rowIndex } = side
  const anchorKey = anchorKeyOf(input.view, input.selectedCommitSha, file.path, row)
  const lineNumber = String((version === 'old' ? row.oldNumber : row.newNumber) ?? '').padStart(5)
  const isCursor = hasButtons && rowIndex === input.cursorRowIndex

  return (
    <Box width="50%" flexGrow={1} minWidth={0} flexDirection="row" alignItems="flex-start" backgroundColor={isCursor ? ui.theme.cursorBackground : rowBackgroundOf(ui.theme, row.kind)}>
      {hasButtons ? (
        renderAskGutter(ui, rowIndex, anchorKey, isCursor, input)
      ) : (
        <Box width={4} height={1} flexShrink={0} />
      )}
      {hasButtons ? (
        renderLineNumberButton(ui, rowIndex, anchorKey, lineNumber, isCursor, input)
      ) : (
        <Box flexShrink={0} height={1}>
          <Text color={ui.theme.lineNumber}>{lineNumber}</Text>
        </Box>
      )}
      <Box flexShrink={0} height={1}>
        <Text color={rowColorOf(ui.theme, row.kind)}> {ROW_MARKS[row.kind]} </Text>
      </Box>
      {renderCode(ui, row, file.path, input.watchedTerm)}
    </Box>
  )
}

// The [+] shows under the pointer only; the line cursor's arrow sits in the same place otherwise.
function renderAskGutter(ui: ViewElements, rowIndex: number, anchorKey: string, isCursor: boolean, input: DiffViewInput) {
  const { Box, Button, Text } = ui

  return (
    <Box width={4} height={1} flexShrink={0}>
      {isCursor && (
        <Box position="absolute">
          <Text color={ui.theme.accent} bold>
            {' ▶'}
          </Text>
        </Box>
      )}
      <Box display="none" hover={{ display: 'flex' }} backgroundColor={ui.theme.panelBackground}>
        <Button key={`${ASK_BUTTON_KEY_PREFIX}${rowIndex}`} plain label="[+]" onPress={() => input.actions.openQuestion(anchorKey)} />
      </Box>
    </Box>
  )
}

function renderLineNumberButton(
  ui: ViewElements,
  rowIndex: number,
  anchorKey: string,
  label: string,
  isCursor: boolean,
  input: DiffViewInput,
) {
  const { Box, Button } = ui

  return (
    <Box flexShrink={0} height={1}>
      <Button
        key={`${LINE_NUMBER_BUTTON_KEY_PREFIX}${rowIndex}`}
        plain
        dimColor={!isCursor}
        hover={{ color: ui.theme.accent, bold: true }}
        label={label}
        onPress={() => input.actions.openQuestion(anchorKey)}
      />
    </Box>
  )
}

// The highlighter colors a whole line or nothing: a line holding the watched term is drawn plain, the term lit in it.
function renderCode(ui: ViewElements, row: DiffRow, path: string, watchedTerm: string) {
  const { Box, Code, Text } = ui
  let code
  if (row.text.trim() === '') {
    code = <Text> </Text>
  } else if (matchCountOf(row.text, watchedTerm) > 0) {
    code = (
      <Text wrap="wrap" color={ui.theme.text}>
        {splitByTerm(row.text, watchedTerm).map((segment, index) =>
          segment.isMatch ? (
            <Text key={`match-${index}`} bold color={ui.theme.heading} backgroundColor={ui.theme.watchedMatchBackground}>
              {segment.text}
            </Text>
          ) : (
            segment.text
          ),
        )}
      </Text>
    )
  } else {
    code = <Code source={row.text} path={path} language={row.language ?? languageOfPath(path)} wrap="wrap" />
  }

  return (
    <Box flexGrow={1} flexShrink={1} minWidth={0} flexDirection="column">
      {code}
    </Box>
  )
}

function renderRowThreads(ui: ViewElements, row: DiffRow, rowIndex: number, file: ChangedFile, input: DiffViewInput) {
  const { Box } = ui
  const anchorKey = anchorKeyOf(input.view, input.selectedCommitSha, file.path, row)

  return (
    <Box flexDirection="column" flexShrink={0}>
      {input.gitHubThreads
        .filter(thread => isGitHubThreadOnRow(thread, file.path, row))
        .map(thread => renderGitHubThread(ui, thread, gitHubThreadInputOf(input)))}
      {renderThreadsAndQuestion(ui, {
        anchorKey,
        threads: input.threads,
        questionState: input.questionState,
        actions: input.actions,
        ask: question => input.actions.askAboutRow(anchorKey, rowIndex, question),
        armForPrompt: () => input.actions.armRowQuestion(anchorKey, rowIndex),
      })}
    </Box>
  )
}

function gitHubThreadInputOf(input: DiffViewInput) {
  return { expandedThreadIds: input.expandedGitHubThreadIds, currentThreadId: input.currentThreadId, actions: input.actions }
}

export function renderLineShortcuts(ui: ViewElements, input: DiffViewInput) {
  const { Box, Button } = ui
  const shortcuts: Array<{ key: string; action: ShortcutAction; label: string; isMove?: boolean; onPress: () => Promise<void> }> = [
    { key: 'cursor-down', action: 'nextLine', label: '↓ line', isMove: true, onPress: () => input.actions.moveCursor(1) },
    { key: 'cursor-up', action: 'previousLine', label: '↑ line', isMove: true, onPress: () => input.actions.moveCursor(-1) },
    { key: 'hunk-next', action: 'nextHunk', label: '↓ hunk', isMove: true, onPress: () => input.actions.moveCursorToHunk(1) },
    { key: 'hunk-previous', action: 'previousHunk', label: '↑ hunk', isMove: true, onPress: () => input.actions.moveCursorToHunk(-1) },
    { key: ASK_ON_LINE_KEY, action: 'askOnLine', label: input.isOnGitHubThread ? 'address comment' : 'ask', onPress: () => input.actions.askOnCursorLine() },
    { key: 'reply-on-line', action: 'replyOnLine', label: 'reply', onPress: () => input.actions.replyOnCursorLine() },
  ]
  const path = input.selectedFile?.path
  // Kept once the whole file shows: a shortcut whose button vanished would drop the keyboard back to the prompt.
  if (path && !input.selectedFile?.isUntracked) {
    shortcuts.push(
      { key: 'more-context', action: 'moreContext', label: 'context', onPress: () => input.actions.expandContext(path) },
      { key: 'whole-file', action: 'wholeFile', label: 'whole file', onPress: () => input.actions.showWholeFile(path) },
    )
  }
  if (input.canMarkViewed) {
    shortcuts.push({ key: 'mark-viewed-next', action: 'markViewedAndNext', label: 'viewed, next', onPress: () => input.actions.markViewedAndNext() })
  }

  return (
    <Box flexDirection="row" flexShrink={0} height={1} overflow="hidden" paddingX={1}>
      {shortcuts.map(shortcut => {
        const hotkey = input.hotkeyOf(shortcut.action)
        const typedKey = input.keymap[shortcut.action][0] ?? ''
        // A move only names its key; its hidden button carries it.
        if (shortcut.isMove) {
          return (
            <Box key={`box-${shortcut.key}`} marginRight={2} flexShrink={0}>
              {renderShortcutHint(ui, typedKey, shortcut.label, hotkey === undefined)}
              <Box display="none">
                <Button key={shortcut.key} plain hotkey={hotkey} label={shortcut.label} onPress={shortcut.onPress} />
              </Box>
            </Box>
          )
        }
        return (
          <Box key={`box-${shortcut.key}`} marginRight={2} flexShrink={0}>
            <Button
              key={shortcut.key}
              plain
              dimColor={hotkey === undefined}
              hotkey={hotkey}
              label={hotkey === undefined ? `${typedKey}: ${shortcut.label}` : shortcut.label}
              onPress={shortcut.onPress}
            />
          </Box>
        )
      })}
    </Box>
  )
}

files.hooks/view/file-list.tsx:
import type { ChangedFile, PullRequestSummary, StageState, ViewedState } from '../../types'
import { DIRECTORY_BUTTON_KEY_PREFIX, FILE_BUTTON_KEY_PREFIX, FILE_FILTER_KEY, PULL_REQUEST_OVERVIEW_KEY, ROW_CLICK_TARGET_LENGTH } from '../constants'
import type { Keymap, ShortcutAction } from '../keymap'
import { fileNameOf } from '../git-parsing'
import { VIEWED_MARKS } from '../github-review'
import type { FileLine } from '../layout'
import { renderFileStats, renderLineCounts, renderShortcutHint } from './labels'
import type { ExplorerActions, ViewElements } from './types'
import { WATCH_MARK } from './watch-bar'

const GITHUB_COMMENT_MARK = '\u{1F4AC}'
const CLAUDE_THREAD_MARK = '◆'
const PIN_MARK = '\u{1F4CC}'

export type FileListInput = {
  files: ChangedFile[]
  shownFileCount: number
  hiddenNoiseCount: number
  fileFilter: string
  // Empty while nothing is watched.
  watchedMatchCountByPath: Record<string, number>
  isNoiseShown: boolean
  isViewedHidden: boolean
  // A file GitHub does not list in the pull request yet most likely changed in a commit not pushed.
  hasUnpushedCommits: boolean
  fileLines: FileLine[]
  shownFileLines: FileLine[]
  fileListOffset: number
  visibleFileLines: number
  width: number | undefined
  height: number
  // Drawn over the code: its own opaque background, so the code does not show through.
  isDrawer: boolean
  // A drawer on a pane wide enough to take the list beside the code.
  canPin: boolean
  selectedFilePath: string | null
  isOverviewShown: boolean
  pullRequest: PullRequestSummary | null
  viewedStateByPath: Record<string, ViewedState>
  openThreadCountByPath: Record<string, { claudeCount: number; gitHubCount: number }>
  hasStageActions: boolean
  // Null outside the Uncommitted view, where nothing is staged.
  stageStateByPath: Record<string, StageState> | null
  keymap: Keymap
  isTyping: boolean
  hotkeyOf: (action: ShortcutAction) => string | undefined
  actions: ExplorerActions
}

export function renderFileList(ui: ViewElements, input: FileListInput) {
  const { Box, Button, Text } = ui
  const hasMoreAbove = input.fileListOffset > 0
  const hasMoreBelow = input.fileListOffset + input.visibleFileLines < input.fileLines.length

  return (
    <Box
      flexDirection="column"
      width={input.width}
      height={input.height}
      overflow="hidden"
      borderStyle="round"
      borderColor={input.isDrawer ? ui.theme.accentBorder : ui.theme.border}
      backgroundColor={input.isDrawer ? ui.theme.tileFill : ui.theme.panelBackground}
      paddingX={1}
    >
      <Box flexDirection="row">
        <Box flexGrow={1}>
          <Text bold color={ui.theme.heading}>
            Files{'  '}
            {isFiltered(input) ? (
              <Text bold color={ui.theme.filtered}>{`${input.shownFileCount} of ${input.files.length}`}</Text>
            ) : (
              <Text color={ui.theme.muted}>{input.files.length}</Text>
            )}
          </Text>
        </Box>
        {input.pullRequest && (
          <Box key="toggle-viewed-hidden-box" flexShrink={0} marginRight={1}>
            <Button
              key="toggle-viewed-hidden"
              plain
              dimColor={!input.isViewedHidden}
              hover={{ color: ui.theme.accent }}
              label={input.isViewedHidden ? '◉ unviewed' : '○ unviewed'}
              onPress={() => input.actions.toggleViewedHidden()}
            />
          </Box>
        )}
        <Text color={ui.theme.muted}>
          {hasMoreAbove ? '▲' : ' '}
          {hasMoreBelow ? '▼' : ' '}
        </Text>
        {(!input.isDrawer || input.canPin) && (
          <Box flexShrink={0} marginLeft={1}>
            <Button
              key={input.isDrawer ? 'file-list-pin' : 'file-list-collapse'}
              plain
              hotkey={input.hotkeyOf('toggleFileListCollapse')}
              label={input.isDrawer ? `${PIN_MARK} pin` : '⇤ collapse'}
              onPress={() => input.actions.toggleFileListCollapse()}
            />
          </Box>
        )}
      </Box>
      {renderFilter(ui, input)}
      <Box flexDirection="column" height={input.visibleFileLines} overflow="hidden">
        {input.files.length === 0 && <Text color={ui.theme.muted}>Nothing to review in this view.</Text>}
        {input.files.length > 0 && input.shownFileCount === 0 && <Text color={ui.theme.muted}>No file matches the filter.</Text>}
        {input.shownFileLines.map(fileLine => renderFileLine(ui, fileLine, input))}
      </Box>
      {(input.hiddenNoiseCount > 0 || input.isNoiseShown) && renderNoiseNotice(ui, input)}
      {renderNavigationHints(ui, input)}
      {input.selectedFilePath !== null && !input.isOverviewShown && (
        <Box key="fold-directory-box" display="none">
          <Button
            key="fold-current-directory"
            plain
            hotkey={input.hotkeyOf('toggleDirectoryFold')}
            label="fold or unfold the file's directory"
            onPress={() => input.actions.toggleCurrentDirectoryFold()}
          />
        </Box>
      )}
      {input.hasStageActions && renderStageActions(ui, input)}
    </Box>
  )
}

function renderFilter(ui: ViewElements, input: FileListInput) {
  const { Box, Button, Input } = ui

  return (
    <Box flexDirection="row" height={1}>
      <Box flexShrink={0}>
        <Button key="focus-file-filter" plain hotkey={input.hotkeyOf('focusFileFilter')} label="/ " onPress={() => input.actions.focusFileFilter()} />
      </Box>
      <Box flexGrow={1}>
        <Input
          key={FILE_FILTER_KEY}
          value={input.fileFilter}
          placeholder="filter files…"
          onInput={value => input.actions.updateFileFilter(value)}
          onSubmit={value => input.actions.submitFileFilter(value)}
        />
      </Box>
      {isFiltered(input) && (
        <Box key="clear-file-filters-box" flexShrink={0} marginLeft={1}>
          <Button
            key="clear-file-filters"
            plain
            hover={{ color: ui.theme.accent }}
            hotkey={input.hotkeyOf('clearFileFilters')}
            label="✕ clear"
            onPress={() => input.actions.clearFileFilters()}
          />
        </Box>
      )}
    </Box>
  )
}

export function isFiltered(input: Pick<FileListInput, 'files' | 'shownFileCount'>): boolean {
  return input.shownFileCount < input.files.length
}

function renderNoiseNotice(ui: ViewElements, input: FileListInput) {
  const { Box, Button, Text } = ui

  return (
    <Box key="noise-notice" flexDirection="row" height={1} overflow="hidden">
      <Box flexGrow={1}>
        <Text color={ui.theme.muted}>
          {input.isNoiseShown ? 'lockfiles and generated files shown' : `+ ${input.hiddenNoiseCount} lockfile or generated file${input.hiddenNoiseCount > 1 ? 's' : ''} folded`}
        </Text>
      </Box>
      <Button key="toggle-noise" plain hover={{ color: ui.theme.accent }} label={input.isNoiseShown ? ' fold ' : ' show '} onPress={() => input.actions.toggleNoiseShown()} />
    </Box>
  )
}

function renderFileLine(ui: ViewElements, fileLine: FileLine, input: FileListInput) {
  const { Text } = ui
  if (fileLine.kind === 'spacer') {
    return <Text> </Text>
  }
  if (fileLine.kind === 'directory') {
    return renderDirectoryLine(ui, fileLine, input)
  }
  if (fileLine.kind === 'overview') {
    return renderOverviewLine(ui, input)
  }

  return renderChangedFileLine(ui, fileLine.file, input)
}

function renderDirectoryLine(ui: ViewElements, fileLine: Extract<FileLine, { kind: 'directory' }>, input: FileListInput) {
  const { Box, Button, Text } = ui

  return (
    <Box flexDirection="row" height={1}>
      <Box key={`directory-box-${fileLine.directory}`} flexShrink={0}>
        <Button
          key={`${DIRECTORY_BUTTON_KEY_PREFIX}${fileLine.directory}`}
          plain
          hover={{ color: ui.theme.accent, bold: true }}
          label={fileLine.isFolded ? '▸ ' : '▾ '}
          onPress={() => input.actions.toggleDirectoryFold(fileLine.directory)}
        />
      </Box>
      <Box flexGrow={1} flexShrink={1} minWidth={0} overflow="hidden">
        <Text color={ui.theme.directory} wrap="truncate-start">
          {fileLine.directory === '' ? './' : `${fileLine.directory}/`}
        </Text>
      </Box>
      {fileLine.isFolded && (
        <Box flexShrink={0} marginLeft={1}>
          <Text color={ui.theme.muted}>
            {fileLine.fileCount} file{fileLine.fileCount > 1 ? 's' : ''}
          </Text>
        </Box>
      )}
    </Box>
  )
}

function renderSelectionMark(ui: ViewElements, isSelected: boolean) {
  const { Box, Text } = ui

  return (
    <Box width={2} flexShrink={0}>
      <Text color={ui.theme.accent}>{isSelected ? '▎' : ' '}</Text>
    </Box>
  )
}

function renderOverviewLine(ui: ViewElements, input: FileListInput) {
  const { Box, Button, Text } = ui

  return (
    <Box flexDirection="row" height={1} backgroundColor={input.isOverviewShown ? ui.theme.selectedBackground : undefined}>
      {renderSelectionMark(ui, input.isOverviewShown)}
      <Box width={4} flexShrink={0}>
        <Text color={ui.theme.accent} bold>
          ≡
        </Text>
      </Box>
      <Box flexGrow={1} flexShrink={1} height={1} overflow="hidden">
        <Button key={PULL_REQUEST_OVERVIEW_KEY} plain label={'Overview'.padEnd(ROW_CLICK_TARGET_LENGTH)} onPress={() => input.actions.showOverview()} />
      </Box>
      <Box flexShrink={0} marginLeft={1}>
        {renderLineCounts(ui, input.pullRequest?.additions ?? 0, input.pullRequest?.deletions ?? 0)}
      </Box>
    </Box>
  )
}

function renderChangedFileLine(ui: ViewElements, file: ChangedFile, input: FileListInput) {
  const { Box, Button, Text } = ui
  const isSelected = !input.isOverviewShown && file.path === input.selectedFilePath
  const viewedState = input.viewedStateByPath[file.path]
  const { claudeCount = 0, gitHubCount = 0 } = input.openThreadCountByPath[file.path] ?? {}
  const openThreadsLabel = [
    claudeCount > 0 ? `${CLAUDE_THREAD_MARK} ${claudeCount}` : null,
    gitHubCount > 0 ? `${GITHUB_COMMENT_MARK} ${gitHubCount}` : null,
  ]
    .filter(part => part !== null)
    .join(' ')
  const change = changeLetterOf(file)

  return (
    <Box flexDirection="row" height={1} backgroundColor={isSelected ? ui.theme.selectedBackground : undefined}>
      {renderSelectionMark(ui, isSelected)}
      {input.stageStateByPath && (
        <Box width={3} flexShrink={0}>
          {renderStageMark(ui, file.path, input.stageStateByPath[file.path] ?? 'unstaged', input)}
        </Box>
      )}
      <Box width={2} flexShrink={0}>
        <Text color={ui.theme[change.color]} bold>
          {change.letter}
        </Text>
      </Box>
      <Box flexGrow={1} flexShrink={1} height={1} overflow="hidden">
        <Button
          key={`${FILE_BUTTON_KEY_PREFIX}${file.path}`}
          plain
          dimColor={viewedState === 'VIEWED'}
          label={fileNameOf(file.path).padEnd(ROW_CLICK_TARGET_LENGTH)}
          onPress={() => input.actions.selectFile(file.path)}
        />
      </Box>
      {(input.watchedMatchCountByPath[file.path] ?? 0) > 0 && (
        <Box key={`watch-count-box-${file.path}`} flexShrink={0} marginLeft={1}>
          <Text color={ui.theme.watched}>
            {WATCH_MARK} {input.watchedMatchCountByPath[file.path]}
          </Text>
        </Box>
      )}
      {openThreadsLabel !== '' && (
        <Box key={`threads-box-${file.path}`} flexShrink={0} marginLeft={1}>
          <Button
            key={`threads-${file.path}`}
            plain
            hover={{ color: ui.theme.accent, bold: true }}
            label={openThreadsLabel}
            onPress={() => input.actions.openFirstThreadOfFile(file.path)}
          />
        </Box>
      )}
      <Box flexShrink={0} marginLeft={1}>
        {renderFileStats(ui, file)}
      </Box>
      {input.pullRequest && (
        <Box key={`viewed-box-${file.path}`} width={4} flexShrink={0} marginLeft={1}>
          {viewedState ? (
            <Button
              key={`viewed-${file.path}`}
              plain
              dimColor={viewedState !== 'VIEWED'}
              hover={{ color: ui.theme.accent, bold: true }}
              label={VIEWED_MARKS[viewedState]}
              onPress={() => input.actions.toggleViewed(file.path)}
            />
          ) : (
            <Text color={ui.theme.lineNumber}>{input.hasUnpushedCommits ? ' ↑ ' : ' · '}</Text>
          )}
        </Box>
      )}
    </Box>
  )
}

function renderNavigationHints(ui: ViewElements, input: FileListInput) {
  const { Box, Button } = ui
  const hints: Array<{ arrow: string; action: ShortcutAction; act: () => Promise<void> }> = [
    { arrow: '↑', action: 'previousFile', act: () => input.actions.moveFileSelection(-1) },
    { arrow: '↓', action: 'nextFile', act: () => input.actions.moveFileSelection(1) },
    { arrow: '←', action: 'previousView', act: () => input.actions.moveView(-1) },
    { arrow: '→', action: 'nextView', act: () => input.actions.moveView(1) },
  ]

  // The row names the keys; their hidden buttons carry them.
  return (
    <Box flexDirection="row" marginTop={1} height={1} overflow="hidden">
      {hints.flatMap(hint =>
        input.keymap[hint.action].map(hotkey => (
          <Box key={`navigate-hint-${hotkey}`} marginRight={2} flexShrink={0}>
            {renderShortcutHint(ui, hotkey, hint.arrow, input.isTyping)}
          </Box>
        )),
      )}
      <Box display="none">
        {hints.flatMap(hint =>
          input.keymap[hint.action].map(hotkey => (
            <Button key={`navigate-${hotkey}`} plain hotkey={input.isTyping ? undefined : hotkey} label={hint.arrow} onPress={hint.act} />
          )),
        )}
      </Box>
    </Box>
  )
}

function renderStageMark(ui: ViewElements, path: string, stageState: StageState, input: FileListInput) {
  const { Button, Text } = ui
  switch (stageState) {
    case 'staged':
      return <Text color={ui.theme.added}> ✓</Text>
    case 'partlyStaged':
    case 'unstaged':
      return (
        <Button
          key={`stage-${path}`}
          plain
          label={stageState === 'partlyStaged' ? ' ±' : ' +'}
          onPress={() => input.actions.stageFile(path)}
        />
      )
  }
}

function renderStageActions(ui: ViewElements, input: FileListInput) {
  const { Box, Button } = ui

  return (
    <Box flexDirection="row" height={1} overflow="hidden">
      <Box marginRight={2}>
        <Button
          key="stage-current"
          plain
          hotkey={input.hotkeyOf('stageCurrentFile')}
          label="add file"
          onPress={() => input.actions.stageCurrentFile()}
        />
      </Box>
      <Button
        key="stage-all"
        plain
        hotkey={input.hotkeyOf('stageAllChanges')}
        label="add all"
        onPress={() => input.actions.stageAllChanges()}
      />
    </Box>
  )
}

// A for a file the change creates (or git does not track yet), D for one it deletes, M for one it modifies.
function changeLetterOf(file: ChangedFile): { letter: string; color: 'added' | 'removed' | 'commitSha' } {
  if (file.isUntracked || file.creation === 'created') {
    return { letter: 'A', color: 'added' }
  }

  return file.creation === 'deleted' ? { letter: 'D', color: 'removed' } : { letter: 'M', color: 'commitSha' }
}

files.hooks/view/header.tsx:
import type { PullRequestSummary, ReviewView } from '../../types'
import { HEADER_COLUMNS_WITHOUT_TILES, VIEW_LABELS, VIEW_ORDER, VIEW_SHORTCUTS } from '../constants'
import type { ShortcutAction } from '../keymap'
import { LINES_TO_VIEW_TILE_LABEL, progressBarCells } from './drawings'
import type { HeaderTile } from './drawings'
import type { ExplorerActions, GitHubPage, ViewElements } from './types'
import { WATCH_MARK } from './watch-bar'

export function renderHeader(
  ui: ViewElements,
  input: {
    view: ReviewView
    location: string
    uncommittedFileCount: number
    branchCommitCount: number
    unpushedCommitCount: number
    pullRequest: PullRequestSummary | null
    viewedCount: { viewed: number; total: number }
    linesToView: { addedLines: number; removedLines: number }
    tiles: HeaderTile[]
    bodyColumns: number
    gitHubPage: GitHubPage | null
    hotkeyOf: (action: ShortcutAction) => string | undefined
    actions: ExplorerActions
  },
) {
  const { Box, Text } = ui
  const { gitHubPage, pullRequest, viewedCount } = input
  const tiles = tilesThatFit(input.tiles, input.bodyColumns)

  // The tabs' row is as tall as the tiles: the layout counts three rows for it, one for the location, one for the pull
  // request's line and one left empty under the header.
  return (
    <Box flexDirection="column" paddingLeft={1} paddingBottom={1}>
      <Box flexDirection="row" alignItems="center" height={3}>
        {VIEW_ORDER.map(view => {
          const isActive = view === input.view
          return renderPill(ui, {
            key: `view-${view}`,
            hotkey: input.hotkeyOf(VIEW_SHORTCUTS[view]),
            text: viewTabTextOf(view, input),
            isActive,
            isDim: !isActive,
            isEmpty: view === 'uncommitted' && input.uncommittedFileCount === 0,
            onPress: () => input.actions.switchView(view),
            marginRight: 1,
          })
        })}
        <Box flexGrow={1} />
        {tiles.map(tile => renderTerminalTile(ui, tile))}
        {gitHubPage &&
          renderPill(ui, {
            key: 'open-on-github',
            hotkey: input.hotkeyOf('openOnGitHub'),
            text: `${gitHubPage.description} on GitHub ↗`,
            onPress: () => input.actions.openOnGitHub(gitHubPage),
            marginLeft: 1,
            // The pull request's own page already has its link under the tabs, PR #n; the key still opens it.
            isHidden: gitHubPage.url === pullRequest?.url,
          })}
        {renderPill(ui, { key: 'watch-selection', hotkey: input.hotkeyOf('watchSelection'), text: WATCH_MARK, onPress: () => input.actions.watchSelection(), marginLeft: 1 })}
        {renderPill(ui, { key: 'help', hotkey: input.hotkeyOf('toggleHelp'), text: 'help', onPress: () => input.actions.toggleHelp(), marginLeft: 1 })}
        {renderPill(ui, { key: 'refresh', text: 'refresh', onPress: () => input.actions.refresh(), marginLeft: 1 })}
        {renderPill(ui, { key: 'close', text: 'close', onPress: () => input.actions.close(), marginLeft: 1 })}
      </Box>
      <Box height={1} overflow="hidden" marginLeft={2}>
        <Text color={ui.theme.muted} wrap="truncate-start">
          {input.location}
        </Text>
      </Box>
      {pullRequest && renderPullRequestLine(ui, pullRequest, viewedCount, input.linesToView, {
          isViewedTileShown: tiles.some(tile => tile.kind === 'progress'),
          isLinesToViewTileShown: tiles.some(tile => tile.kind === 'lines' && tile.label === LINES_TO_VIEW_TILE_LABEL),
        })}
    </Box>
  )
}

function renderPullRequestLine(
  ui: ViewElements,
  pullRequest: PullRequestSummary,
  viewedCount: { viewed: number; total: number },
  linesToView: { addedLines: number; removedLines: number },
  shownTiles: { isViewedTileShown: boolean; isLinesToViewTileShown: boolean },
) {
  const { Box, Link, Text } = ui

  return (
    <Box flexDirection="row" height={1} overflow="hidden" marginLeft={2}>
      <Text color={ui.theme.accent} bold>
        <Link href={pullRequest.url}>PR #{pullRequest.number} ↗</Link>
      </Text>
      {!shownTiles.isViewedTileShown && (
        <Text color={viewedCount.viewed === viewedCount.total ? ui.theme.added : ui.theme.muted}>
          {'  ·  '}
          {viewedCount.viewed}/{viewedCount.total} files viewed on GitHub
        </Text>
      )}
      {!shownTiles.isLinesToViewTileShown && viewedCount.viewed < viewedCount.total && (
        <Text color={ui.theme.muted}>
          {shownTiles.isViewedTileShown ? '  ·  ' : ', '}
          <Text color={ui.theme.added}>+{linesToView.addedLines}</Text> <Text color={ui.theme.removed}>−{linesToView.removedLines}</Text>
          {' to view'}
        </Text>
      )}
    </Box>
  )
}

type Pill = {
  key: string
  hotkey?: string
  text: string
  isActive?: boolean
  isDim?: boolean
  // Drawn without its fill: the view holds nothing.
  isEmpty?: boolean
  isHidden?: boolean
  onPress: () => Promise<void>
  marginLeft?: number
  marginRight?: number
}

function viewTabTextOf(view: ReviewView, counts: { uncommittedFileCount: number; branchCommitCount: number; unpushedCommitCount: number }): string {
  switch (view) {
    case 'uncommitted':
      return counts.uncommittedFileCount > 0 ? `${VIEW_LABELS[view]} ${counts.uncommittedFileCount}` : VIEW_LABELS[view]
    case 'commits': {
      const unpushedMark = counts.unpushedCommitCount > 0 ? ` ↑${counts.unpushedCommitCount}` : ''
      return counts.branchCommitCount > 0 ? `${VIEW_LABELS[view]} ${counts.branchCommitCount}${unpushedMark}` : `${VIEW_LABELS[view]}${unpushedMark}`
    }
    case 'pr':
      return VIEW_LABELS[view]
  }
}

// The terminal takes a Button's click on its label alone: the pill is that label on a fill, with no border or padding
// around it, so a click anywhere on it presses. A plain Button draws its hotkey before the label (`1: `).
function renderPill(ui: ViewElements, pill: Pill) {
  const { Box, Button } = ui

  return (
    <Box
      key={`${pill.key}-box`}
      display={pill.isHidden ? 'none' : 'flex'}
      flexShrink={0}
      height={1}
      backgroundColor={pill.isActive ? ui.theme.accentBorder : pill.isEmpty ? undefined : ui.theme.border}
      marginLeft={pill.marginLeft}
      marginRight={pill.marginRight}
    >
      <Button
        key={pill.key}
        plain
        dimColor={pill.isDim}
        hotkey={pill.hotkey}
        label={pill.hotkey ? `${pill.text} ` : ` ${pill.text} `}
        onPress={pill.onPress}
      />
    </Box>
  )
}

// The last tiles give way first when the header runs out of room.
function tilesThatFit(tiles: HeaderTile[], bodyColumns: number): HeaderTile[] {
  const fittingTiles = [...tiles]
  while (fittingTiles.length > 0 && HEADER_COLUMNS_WITHOUT_TILES + terminalTilesColumns(fittingTiles) > bodyColumns) {
    fittingTiles.pop()
  }

  return fittingTiles
}

const TERMINAL_PROGRESS_CELLS = 8
// A tile's frame and inner padding, and the gap before it.
const TERMINAL_TILE_CHROME_COLUMNS = 5

function terminalTilesColumns(tiles: HeaderTile[]): number {
  return tiles.reduce((columns, tile) => columns + terminalTileText(tile).length + TERMINAL_TILE_CHROME_COLUMNS, 0)
}

function terminalTileText(tile: HeaderTile): string {
  if (tile.kind === 'lines') {
    return `${tile.label} +${tile.addedLines} −${tile.removedLines}`
  }
  if (tile.kind === 'progress') {
    return `${tile.label} ${tile.done}/${tile.total} ${' '.repeat(TERMINAL_PROGRESS_CELLS)}`
  }

  return `${tile.label} ${tile.value}`
}

function renderTerminalTile(ui: ViewElements, tile: HeaderTile) {
  const { Box, Text } = ui
  const label = <Text color={ui.theme.muted}>{tile.label} </Text>
  let value
  if (tile.kind === 'lines') {
    value = (
      <Text bold>
        <Text color={ui.theme.added}>+{tile.addedLines}</Text> <Text color={ui.theme.removed}>−{tile.removedLines}</Text>
      </Text>
    )
  } else if (tile.kind === 'progress') {
    const isComplete = tile.total > 0 && tile.done >= tile.total
    const bar = progressBarCells(tile.done, tile.total, TERMINAL_PROGRESS_CELLS)
    value = (
      <Text>
        <Text bold color={isComplete ? ui.theme.added : ui.theme.heading}>
          {tile.done}/{tile.total}{' '}
        </Text>
        <Text color={isComplete ? ui.theme.added : ui.theme.accent} backgroundColor={ui.theme.border}>
          {bar.filled}
        </Text>
        <Text backgroundColor={ui.theme.border}>{bar.rest}</Text>
      </Text>
    )
  } else {
    value = (
      <Text bold color={ui.theme.heading}>
        {tile.value}
      </Text>
    )
  }

  return (
    <Box
      key={`tile-${tile.label}`}
      flexShrink={0}
      marginLeft={1}
      paddingX={1}
      borderStyle="round"
      borderColor={ui.theme.border}
      backgroundColor={ui.theme.panelBackground}
    >
      <Text>
        {label}
        {value}
      </Text>
    </Box>
  )
}

