      <Box flexGrow={1}>
        <Input
          key={WATCH_FIELD_KEY}
          value={input.term}
          placeholder="search all changes…"
          onInput={value => actions.updateWatchedTerm(value)}
          onSubmit={value => actions.submitWatchedTerm(value)}
